  return new Promise(resolve => {
    const response = {
      writeHead(statusCode, headers) { this.statusCode = statusCode; this.headers = headers; },
      end(body) { resolve({ body: body?.toString('utf8') ?? '', headers: this.headers, statusCode: this.statusCode }); }
